    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            if operand[i + 1] != 0:
                result //= operand[i + 1]
            else:
                return "Division by zero error"
        elif operator[i] == '**':
            result **= operand[i + 1]

    return result

