def fibfib(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        fib_dict = {0: 0, 1: 0, 2: 1}
        return fib_helper(n, fib_dict)

def fib_helper(n, fib_dict):
    if n in fib_dict:
        return fib_dict[n]
